{"content": """"Minimal MCP stdio handshake against gbrain serve: initialize -> tools/list."""
import json
import subprocess
import sys

GBRAIN = "/harness-state/.bun/bin/gbrain"
CMD = [GBRAIN, "serve", "--surface", "starter", "--advertise", "verbs"]

p = subprocess.Popen(
    CMD,
    stdin=subprocess.PIPE,
    stdout=subprocess.PIPE,
    stderr=subprocess.PIPE,
    text=True,
    bufsize=1,
)


def send(obj):
    p.stdin.write(json.dumps(obj) + "\n")
    p.stdin.flush()


def read_msg():
    line = p.stdout.readline()
    if not line:
        return None
    return json.loads(line)


send({
    "jsonrpc": "2.0", "id": 1, "method": "initialize",
    "params": {
        "protocolVersion": "2025-06-18",
        "capabilities": {},
        "clientInfo": {"name": "hermes-probe", "version": "0"},
    },
})
init = read_msg()
print("INIT:", json.dumps(init)[:600] if init else "NONE")

send({"jsonrpc": "2.0", "method": "notifications/initialized", "params": {}})
send({"jsonrpc": "2.0", "id": 2, "method": "tools/list", "params": {}})

tools = None
for _ in range(20):
    m = read_msg()
    if m is None:
        break
    if m.get("id") == 2:
        tools = m
        break

if tools and "result" in tools:
    names = [t["name"] for t in tools["result"].get("tools", [])]
    print("TOOL_COUNT:", len(names))
    print("TOOLS:", ", ".join(sorted(names)))
else:
    print("TOOLS_ERR:", json.dumps(tools)[:400] if tools else "no response")

p.stdin.close()
try:
    p.wait(timeout=10)
except Exception:
    p.kill()
err = p.stderr.read()[:800]
if err.strip():
    print("STDERR:", err)
", "path": "/harness-state/gbrain-mcp-probe.py"}

